import React from 'react';
import { Line } from 'react-chartjs-2';

const ComparisonCharts = ({ results }) => {

    if (!results || !results.rewards) {
        return <p>No simulation data yet.</p>;
    }

    const chartData = {
        labels: results.rewards.map((_, index) => index + 1),
        datasets: [
            {
                label: 'DQN Reward per Episode',
                data: results.rewards,
                borderColor: 'rgba(75,192,192,1)',
                backgroundColor: 'rgba(75,192,192,0.2)',
                fill: true
            }
        ]
    };

    const options = {
        responsive: true,
        scales: {
            y: {
                beginAtZero: false
            }
        }
    };

    return (
        <div>
            <h2>Simulation Reward Trend</h2>
            <Line data={chartData} options={options} />
        </div>
    );
};

export default ComparisonCharts;
